const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const errors=t=>t.exception||t.model_audit_error||t.api_error||t.reward==null;
const passed=ts=>ts.reduce((n,t)=>n+(t.reward===1?1:0),0);
function taskScore(ts){if(!ts.length)return 'Pending';const scored=ts.filter(t=>t.reward!=null);return `${passed(ts)} / 3${ts.length<3?` · ${ts.length}/3 finished`:''}${ts.some(errors)?' · error':''}${scored.length<ts.length?' · unscored':''}`;}
function state(r){return r.decision?(r.decision.reason==='critic_rejected'?'Critic rejected':r.decision.accepted?'Kept':'Discarded'):(r.critic?.approved===false?'Critic rejected':r.trials.length===6?'Awaiting decision':r.critic?'Testing':r.proposal?'In review':'Preparing');}
function roundView(r){const status=state(r),d=r.decision;const descriptions={
1:'Prompt only. Added an experiment planning guide, working notes, model-validation advice, and checks before submission.',
2:'Prompt + proposed helper tools. Added experiment tracking and model checks, but also embedded specific outcomes and task-tuned defaults from previous trials. The critic rejected it before testing.',
3:'Prompt + a model-checking tool. Removed the task-specific numbers, added forward validation and prediction diagnostics, and tested the candidate. It passed 2 of 6 trials, so Round 1 remained the parent.',
4:'Prompt + two optional tools, starting from Round 1. Added hit tracking and forward validation, a batch-file auditor, and a rewritten model checker that supports plain predict() functions. Its effect is still being tested.'
};let overview=descriptions[r.number]||'Read the proposal and exact changes below.' ;const verdict=d?(d.reason==='critic_rejected'?'No benchmark trials were run. The previous version stays.':d.accepted?'This candidate becomes the parent for the next round.':'The previous version stays. This candidate’s evidence remains available to later rounds.'):'No selection decision has been recorded yet.';const critic=r.critic?.approved===true?'Approved for testing. The critic checked the experimental boundaries; performance still has to be measured.':r.critic?.approved===false?'Rejected before testing. See the critic’s reasons below.':'The critic has not returned a decision yet.';
 document.getElementById('round-content').innerHTML=`<div class="round-top"><h3>Round ${r.number}</h3><span class="tag ${status.toLowerCase()}">${esc(status)}</span></div><p class="round-summary">${overview}</p><div class="round-facts"><div><h4>Critic’s check</h4><p>${critic}</p></div><div><h4>What happened next?</h4><p>${verdict} ${d?.reason==='critic_rejected'?'':r.trials.length+'/6 trial outcomes recorded.'}</p></div></div><details><summary>Read the full proposal</summary><div class="prose">${esc(r.proposal||'The proposal is still being prepared.')}</div></details><details><summary>Read the critic’s reasons</summary><div class="prose">${esc(r.critic?.reasons?.join('\n\n')||(typeof r.critic==='string'?r.critic:'No critic report yet.'))}</div></details><details><summary>See the exact changes</summary><pre>${esc(r.diff||'No edit recorded yet.')}</pre></details><details><summary>Inspect individual trial outcomes (${r.trials.length}/6)</summary><ul class="trial-list">${r.trials.map(t=>`<li>${esc(t.trial)}: ${t.reward==null?'Unscored':t.reward===1?'Pass':'Fail'}${errors(t)?' · execution error (retained in the record)':''}</li>`).join('')||'<li>No completed trial records yet.</li>'}</ul></details><details><summary>Source hashes and selection record</summary><pre>${esc(JSON.stringify({source:r.source,decision:d},null,2))}</pre></details>`;
}
fetch('experiment.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json();}).then(data=>{
 const rounds=data.rounds,complete=data.trials.length,latest=rounds.at(-1);document.getElementById('run-state').textContent=data.stopped?'Experiment stopped':data.selected?'Experiment complete':`Round ${latest?.number||1} in progress`;
 document.getElementById('run-detail').textContent=data.stopped?`${complete} trial outcomes preserved. ${data.stopped.message}`:data.selected?`${complete} trial outcomes recorded across ${rounds.length} rounds. These are evolve scores.`:`${latest?state(latest):'Preparing'} · ${complete} completed trial records so far. This page is a published snapshot, not a live feed.`;
 document.getElementById('score-chart').innerHTML=rounds.map(r=>{const finished=r.trials.length===6&&r.trials.every(t=>t.reward!=null);const pct=passed(r.trials)/6*100;return `<div class="bar-row"><span>Round ${r.number}</span><div class="bar-track ${finished?'':'pending'}" role="img" aria-label="${finished?pct.toFixed(1)+' percent':'Evaluation incomplete'}">${finished?`<div class="bar-fill" style="width:${pct}%"></div>`:''}</div><span class="bar-value">${r.decision?.reason==='critic_rejected'?'Not run':finished?pct.toFixed(1)+'%':r.trials.length+'/6 done'}</span></div>`;}).join('')||'<p class="chart-note">No candidates have been evaluated yet.</p>';
 document.getElementById('scores').innerHTML=rounds.map(r=>`<tr><td>Round ${r.number}</td><td>${r.decision?.reason==='critic_rejected'?'Not run':taskScore(r.trials.filter(t=>t.task==='propylene-active-learning'))}</td><td>${r.decision?.reason==='critic_rejected'?'Not run':taskScore(r.trials.filter(t=>t.task==='suzuki-condition-screen'))}</td><td>${r.decision?.reason==='critic_rejected'?'Not evaluated':r.trials.length?passed(r.trials)+' / 6'+(r.trials.length<6?' · pending':''):'Pending'}</td><td><span class="tag ${state(r).toLowerCase()}">${esc(state(r))}</span></td></tr>`).join('')||'<tr><td colspan="5">No candidate records yet.</td></tr>';
 const tabs=document.getElementById('round-tabs');tabs.innerHTML=rounds.map((r,i)=>`<button role="tab" aria-controls="round-content" aria-selected="${i===rounds.length-1}" data-round="${i}">Round ${r.number}</button>`).join('');document.getElementById('round-content').setAttribute('role','tabpanel');tabs.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{tabs.querySelectorAll('button').forEach(t=>t.setAttribute('aria-selected',String(t===b)));roundView(rounds[Number(b.dataset.round)]);}));if(latest)roundView(latest);else document.getElementById('round-content').textContent='The first proposal will appear here when it finishes.';
 const policy=data.trials.reduce((n,t)=>n+(t.agent_result?.cost_usd||0),0),roles=data.role_calls.reduce((n,r)=>n+(r.list_price_estimate_usd||0),0);const output=data.trials.reduce((n,t)=>n+(t.agent_result?.n_output_tokens||0),0);document.getElementById('usage').textContent=`${data.role_calls.length} completed analyst, proposer and critic calls; ${complete} trial outcomes. Recorded task output: ${output.toLocaleString()} tokens. CLI list-price estimates: $${policy.toFixed(2)} for task runs and $${roles.toFixed(2)} for revision roles. These are estimates, not subscription charges; unfinished calls are excluded.`;document.getElementById('updated').textContent=`Snapshot: ${new Date(data.updated_at).toLocaleString('en-US',{timeZone:'UTC',dateStyle:'medium',timeStyle:'short'})} UTC`;
}).catch(()=>{document.getElementById('run-state').textContent='Results unavailable';document.getElementById('run-detail').textContent='The experiment snapshot could not be loaded. Reload the page to try again.';});
